import {describe,it,expect} from 'vitest';
import {normalCDF,normalPDF,blackScholesPrice,calculateIV,calculateGreeks} from '../../greeks/index.js';
// Independent reference constants from the standard Gaussian integral / Python math.erf,
// not values generated by the implementation under test. NIST DLMF 7.1, 7.20.
describe('independent Gaussian and European pricing benchmarks',()=>{
 it('matches standard normal table values and has the correct density derivative',()=>{for(const [x,value] of [[0,.5],[.1,.539827837277029],[1,.841344746068543],[2,.977249868051821],[3,.99865010196837],[-1,.158655253931457]])expect(Math.abs(normalCDF(x)-value)).toBeLessThan(1e-7);for(const x of [-2,-1,0,1,2]){const h=.0001;expect(Math.abs((normalCDF(x+h)-normalCDF(x-h))/(2*h)-normalPDF(x))).toBeLessThan(1e-5);}});
 it('matches independently computed call/put prices, including exact-future zero-rate pricing',()=>{for(const [spotPrice,strikePrice,timeToExpiry,riskFreeRate,iv,call,put] of [[100,100,1,.05,.2,10.450583572185565,5.573526022256971],[6000,6000,15/365,0,.09,43.671388414955345,43.671388414955345],[100,110,.5,0,.3,4.745683813458079,14.745683813458086]]){for(const [optionType,expected] of [['CE',call],['PE',put]] as const)expect(Math.abs(blackScholesPrice({spotPrice,strikePrice,timeToExpiry,riskFreeRate,iv,optionType})-expected)).toBeLessThan(.001);}});
 it('recovers IV and delta from independent option-price references',()=>{expect(calculateIV(10.450583572185565,100,100,1,.05,'CE')).toBeCloseTo(.2,5);expect(calculateGreeks({spotPrice:100,strikePrice:100,timeToExpiry:1,riskFreeRate:.05,iv:.2,optionType:'CE'}).delta).toBeCloseTo(.6368306511756191,6);});
});
